cyoAdventure = function (a) {
    const ans = campaignTrail_temp.player_answers[campaignTrail_temp.player_answers.length - 1];
    e.noCounter = campaignTrail_temp.player_answers.length;
    // question swap CYOA here
    if (ans == 5016) {
        questionSwapper(1034, 151138);

        // Candidate: Dewey -> Harry Truman (name + banner image)
        if (Number(campaignTrail_temp.candidate_id) === 11001) {
            setCandidateIdentity(11001, { first: "Harry", last: "Truman" });
            campaignTrail_temp.candidate_last_name = "Truman";
            campaignTrail_temp.candidate_image_url = "https://upload.wikimedia.org/wikipedia/commons/c/cf/Harry_S._Truman.jpg?utm_source=commons.wikimedia.org&utm_campaign=index&utm_content=original";

            // Running mate: Truman -> Barkley (name + banner image)
            campaignTrail_temp.running_mate_last_name = "Barkley";
            campaignTrail_temp.running_mate_image_url = "https://upload.wikimedia.org/wikipedia/commons/2/25/Senator_Alben_W._Barkley%2C_seated_at_desk_LCCN2016820089.jpg?utm_source=commons.wikimedia.org&utm_campaign=index&utm_content=original";

            // Achievement
            if (typeof unlockAchievement === "function") {
                unlockAchievement("Come for the King Best Not Miss");
            }
        }
    }

}
